<?php
require '../config/config.php'; role(['administrator','pustakawan']);
$pdo->exec("CREATE TABLE IF NOT EXISTS barcode_history(id INT AUTO_INCREMENT PRIMARY KEY,copy_id INT NOT NULL,old_code VARCHAR(80) NOT NULL,new_code VARCHAR(80) NOT NULL,reason VARCHAR(255) NOT NULL,changed_by INT NULL,changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(copy_id)) ENGINE=InnoDB");
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$a=$_POST['action']??'';
  if($a==='add'){$pdo->prepare('INSERT INTO copies(book_id,code,location_id,condition_status,status) VALUES(?,?,?,?,?)')->execute([(int)$_POST['book_id'],trim($_POST['code']),(int)($_POST['location_id']??0)?:null,$_POST['condition_status'],$_POST['status']]);setmsg('Eksemplar berhasil ditambahkan.');}
  elseif($a==='update'){$pdo->prepare('UPDATE copies SET location_id=?,condition_status=?,status=? WHERE id=?')->execute([(int)($_POST['location_id']??0)?:null,$_POST['condition_status'],$_POST['status'],(int)$_POST['id']]);setmsg('Data eksemplar diperbarui.');}
  elseif($a==='barcode'){$id=(int)$_POST['id'];$new=trim($_POST['new_code']);$reason=trim($_POST['reason']);if(!$new||!$reason)throw new Exception('Barcode baru dan alasan wajib diisi.');$q=$pdo->prepare('SELECT code FROM copies WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn();if(!$old)throw new Exception('Eksemplar tidak ditemukan.');$q=$pdo->prepare('SELECT id FROM copies WHERE code=? AND id<>?');$q->execute([$new,$id]);if($q->fetch())throw new Exception('Barcode baru sudah digunakan.');$pdo->beginTransaction();$pdo->prepare('UPDATE copies SET code=? WHERE id=?')->execute([$new,$id]);$pdo->prepare('INSERT INTO barcode_history(copy_id,old_code,new_code,reason,changed_by) VALUES(?,?,?,?,?)')->execute([$id,$old,$new,$reason,$_SESSION['u']['id']??null]);$pdo->commit();setmsg("Barcode diubah: $old → $new");}
  header('Location:copies.php');exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();setmsg($e->getMessage(),'danger');}
}
$books=$pdo->query('SELECT id,code,title FROM books ORDER BY title')->fetchAll();$locs=$pdo->query('SELECT id,name FROM locations ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT c.*,b.code book_code,b.title,l.name location_name FROM copies c JOIN books b ON b.id=c.book_id LEFT JOIN locations l ON l.id=c.location_id ORDER BY b.title,c.code')->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Eksemplar Buku</title><link rel=stylesheet href=../public/style.css><style>.copygrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.copy-actions details{margin:4px 0}.copy-actions summary{cursor:pointer;color:#1260d1;font-weight:600}@media(max-width:700px){.copygrid{grid-template-columns:1fr}}</style></head><body><div class=layout><?php include '../public/nav.php'?><main class=main><h1>🏷️ Eksemplar Buku & Barcode</h1><?php msg()?><div class=form><h3>Tambah Eksemplar</h3><form method=post><input type=hidden name=action value=add><div class=copygrid><div><label>Buku</label><select name=book_id required><?php foreach($books as $b):?><option value=<?=$b['id']?>><?=e($b['code'].' - '.$b['title'])?></option><?php endforeach?></select></div><div><label>Barcode / Kode Eksemplar</label><input name=code placeholder="BK-0001-01" required></div><div><label>Lokasi / Rak</label><select name=location_id><option value="">-- Pilih --</option><?php foreach($locs as $l):?><option value=<?=$l['id']?>><?=e($l['name'])?></option><?php endforeach?></select></div><div><label>Kondisi</label><select name=condition_status><option>baik</option><option>rusak ringan</option><option>rusak berat</option></select></div><div><label>Status</label><select name=status><option>tersedia</option><option>dipinjam</option><option>rusak</option><option>hilang</option></select></div></div><button>+ Tambah Eksemplar</button></form></div><table class=table><tr><th>Barcode</th><th>Buku</th><th>Lokasi</th><th>Kondisi</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $x):?><tr><td><b><?=e($x['code'])?></b></td><td><?=e($x['title'])?></td><td><?=e($x['location_name']?:'-')?></td><td><?=e($x['condition_status']??'baik')?></td><td><?=e($x['status'])?></td><td class=copy-actions><details><summary>✏️ Kondisi / status</summary><form method=post><input type=hidden name=action value=update><input type=hidden name=id value=<?=$x['id']?>><label>Lokasi</label><select name=location_id><option value="">-- Pilih --</option><?php foreach($locs as $l):?><option value=<?=$l['id']?> <?=$l['id']==$x['location_id']?'selected':''?>><?=e($l['name'])?></option><?php endforeach?></select><label>Kondisi</label><select name=condition_status><?php foreach(['baik','rusak ringan','rusak berat'] as $v):?><option <?=$v===($x['condition_status']??'baik')?'selected':''?>><?=$v?></option><?php endforeach?></select><label>Status</label><select name=status><?php foreach(['tersedia','dipinjam','rusak','hilang'] as $v):?><option <?=$v===$x['status']?'selected':''?>><?=$v?></option><?php endforeach?></select><button>Simpan</button></form></details><details><summary>🔄 Ubah Barcode</summary><form method=post><input type=hidden name=action value=barcode><input type=hidden name=id value=<?=$x['id']?>><label>Barcode Lama</label><input value="<?=e($x['code'])?>" readonly><label>Barcode Baru</label><input name=new_code placeholder="BK-0001-01B" required><label>Alasan</label><select name=reason><option>Barcode rusak</option><option>Label hilang</option><option>Buku diganti</option><option>Kesalahan input</option><option>Lainnya</option></select><button>💾 Simpan Barcode Baru</button></form></details><details><summary>📜 Riwayat Barcode</summary><?php $h=$pdo->prepare('SELECT * FROM barcode_history WHERE copy_id=? ORDER BY changed_at DESC');$h->execute([$x['id']]);$hs=$h->fetchAll();if(!$hs):?><small>Belum ada perubahan barcode.</small><?php else:?><ul><?php foreach($hs as $z):?><li><?=e($z['changed_at'])?> — <?=e($z['old_code'])?> → <b><?=e($z['new_code'])?></b> (<?=e($z['reason'])?>)</li><?php endforeach?></ul><?php endif?></details></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan=6>Belum ada eksemplar.</td></tr><?php endif?></table></main></div></body></html>
